SELECT location, CASE WHEN budget >= 4208000 THEN 'high' WHEN budget >= 1369000 THEN 'mid' ELSE 'low' END AS budget_bucket, COUNT(CASE WHEN location = 'Singapore' THEN 1 END) AS singapore_count, ROUND((100 * SUM(CASE WHEN dept_name = 'Engineering' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_engineering FROM departments GROUP BY location, CASE WHEN budget >= 4208000 THEN 'high' WHEN budget >= 1369000 THEN 'mid' ELSE 'low' END HAVING pct_engineering >= 68;
